// Single source of truth for every Cloudflare worker, binding, var and
// resource this repo deploys. Ported from the gumpbox-landing control plane
// (itself ported from th.legal), 2026-11-25: the repo root IS the
// infrastructure layer.
//
// `infra/scripts/gen-wrangler.ts` derives the per-worker wrangler configs
// from this manifest. The configs are GITIGNORED generated artifacts,
// regenerated by `bun run iac:gen`. Edit the manifest, never the output.
// Deploys run from the repo root via `infra/scripts/deploy.ts`.
//
// Naming rule (same as gumpbox-landing): EVERY Cloudflare resource this repo
// owns carries the `yggdrasight-` prefix: workers, KV namespaces, R2 buckets,
// D1 databases, queues. The account is shared with other projects (gumpbox-*,
// th-legal-*, ...); the prefix is how a resource is traced back here.
//
// Secret VALUES never live in git: this manifest carries names only; set
// values with `wrangler secret put <NAME> --config infra/wrangler/<worker>.jsonc`.
// Cloudflare account: khangtd.09@gmail.com.

export const RESOURCE_PREFIX = 'yggdrasight-';

export interface D1Resource {
  databaseName: `yggdrasight-${string}`;
  /** Empty = name-only binding; wrangler auto-provisions on first deploy. */
  databaseId: string;
}

export interface R2Resource {
  bucketName: `yggdrasight-${string}`;
}

export interface KvResource {
  /** Empty = id-less binding; the FIRST deploy provisions the namespace —
   * pin the returned id back here immediately (an id-less KV binding
   * re-provisions on every deploy, error 10014; th.legal lesson). */
  id: string;
}

export interface Route {
  pattern: string;
  customDomain: boolean;
}

export interface WorkerEntry {
  /** Worker script name on Cloudflare (owner rule: `yggdrasight-` prefix). */
  name: `yggdrasight-${string}`;
  /** Build kind. `opennext` = Next.js app built by @opennextjs/cloudflare
   * (entry `<appDir>/.open-next/worker.js`, assets `<appDir>/.open-next/assets`). */
  kind: 'opennext';
  /** App directory relative to the repo root (pnpm monorepo: apps/web). Workspace
   * packages (@yggdrasight/core, /db) are consumed from source via transpilePackages,
   * so `next build` in appDir is the whole build. */
  appDir: string;
  compatibilityDate: string;
  compatibilityFlags: readonly string[];
  /** Production workers get no debug origins once they have routes. */
  env: 'production' | 'staging';
  /** Build-time env for `next build` (inlined through next.config.ts `env`). */
  buildEnv: Record<string, string>;
  /** Plain vars deployed with the worker (values are not secrets). */
  vars: Record<string, string>;
  kv?: readonly { binding: string; ref: keyof typeof resources.kv }[];
  d1?: readonly { binding: string; ref: keyof typeof resources.d1 }[];
  r2?: readonly { binding: string; ref: keyof typeof resources.r2 }[];
  /** Live routes. A route listed here is attached on the next deploy. */
  routes: readonly Route[];
  /** Routes this worker will own after cutover, NOT attached yet. Moving
   * them into `routes` is the cutover itself and needs the founder's go
   * (attaching a custom domain rewrites public DNS). */
  pendingRoutes?: readonly Route[];
}

export const resources = {
  // None: the landing site is stateless (prerendered pages are served from
  // static assets, see apps/web/open-next.config.ts). The terminal's MongoDB,
  // Redis and Docker workers are NOT on Cloudflare (see infra/docs/ARCHITECTURE.md).
  d1: {} as Record<string, D1Resource>,
  r2: {} as Record<string, R2Resource>,
  kv: {} as Record<string, KvResource>,
};

export const workers = {
  // ─── Public landing site ──────────────────────────────────────────────────
  // apps/web built as the landing deployment (MODE unset = landing, see
  // apps/web/src/middleware.ts): `/` serves /landing, other pages redirect to
  // /landing, /api/* answers 404 (the API needs MongoDB/Redis/Docker workers,
  // which this worker does not have). Same role as `yggdrasight-landing` in
  // ecosystem.config.js.
  landing: {
    name: 'yggdrasight-landing',
    kind: 'opennext',
    appDir: 'apps/web',
    compatibilityDate: '2026-11-01',
    // OpenNext requirements: nodejs_compat for the Next server runtime,
    // global_fetch_strictly_public so fetch() never reaches zone-internal origins.
    compatibilityFlags: ['nodejs_compat', 'global_fetch_strictly_public'],
    env: 'production',
    // LANDING_ONLY=1: no backend behind this build, so middleware answers /api/* with 404.
    buildEnv: { MODE: 'landing', LANDING_ONLY: '1' },
    vars: {},
    // Cutover 2026-11-25 (founder order): apex + www attached as custom domains.
    // The deploy replaces their DNS-only A records pointing at the VPS
    // (51.75.185.38); see infra/docs/DEPLOYMENT.md for rollback.
    // terminal.yggdrasight.com stays on the VPS (not a route here).
    routes: [
      { pattern: 'yggdrasight.com', customDomain: true },
      { pattern: 'www.yggdrasight.com', customDomain: true },
    ],
  },
} as const satisfies Record<string, WorkerEntry>;

/** Secret names per worker (values set via `wrangler secret put`). */
export const secrets = {
  landing: [],
} as const satisfies Record<keyof typeof workers, readonly string[]>;
